#include "f3_mpo_core.hpp"
#include <map>
using Small=std::vector<unsigned char>;
std::vector<GM> deformation(int code,int&degree){constexpr int q=3,D=3,n=27;int f[3][3]{};f[0][0]=1;for(int i=0;i<3;i++)for(int j=0;j<3;j++)if(i||j){f[i][j]=code%3;code/=3;}Small B(n*n),N(n*n);for(int x=0;x<q;x++)for(int y=0;y<q;y++)for(int a=0;a<D;a++)for(int u=0;u<q;u++)for(int v=0;v<q;v++)for(int b=0;b<D;b++){int r=(x*q+y)*D+a,c=(u*q+v)*D+b;if(y==v&&x>=b&&a>=u)B[r*n+c]=f[x-b][a-u];}
for(int r=0;r<n;r++)for(int u=0;u<q;u++)for(int v=0;v<q;v++)for(int b=0;b<D;b++){int c=(u*q+v)*D+b,ce=(v*q+u)*D+b;N[r*n+c]=mod(int(r==c)-B[r*n+ce]);}
std::vector<GM>K(q*q*q*q,GM(D*D));Small C=B;degree=0;
for(int k=0;k<=9;k++){bool nonzero=false;for(auto x:C)nonzero|=x!=0;if(!nonzero){degree=k-1;break;}if(k==9)throw std::runtime_error("N^9 nonzero");for(int x=0;x<q;x++)for(int y=0;y<q;y++)for(int u=0;u<q;u++)for(int v=0;v<q;v++)for(int a=0;a<D;a++)for(int b=0;b<D;b++){int r=(x*q+y)*D+a,c=(u*q+v)*D+b,co=C[r*n+c];auto&t=K[((x*q+y)*q+u)*q+v][D*a+b];if(co==1)t.a|=U(1)<<k;if(co==2)t.b|=U(1)<<k;}Small next(n*n);for(int i=0;i<n;i++)for(int j=0;j<n;j++){int value=0;for(int h=0;h<n;h++)value+=N[i*n+h]*C[h*n+j];next[i*n+j]=value%3;}C=std::move(next);}
for(int x=0;x<q;x++)for(int y=0;y<q;y++)for(int u=0;u<q;u++)for(int v=0;v<q;v++)for(int a=0;a<D;a++)for(int b=0;b<D;b++){T f=K[((x*q+y)*q+u)*q+v][D*a+b];if((std::popcount(f.a)+2*std::popcount(f.b))%3!=(x==v&&y==u&&a==b))throw std::runtime_error("endpoint");}return K;}
int main(int argc,char**argv){std::string path=argc>1?argv[1]:"";int start=argc>2?std::stoi(argv[2]):0,end=argc>3?std::stoi(argv[3]):6561;J=32;PMASK=(U(1)<<32)-1;auto began=std::chrono::steady_clock::now();double best=1e300,bestS=0;int bestCode=-1,bestDegree=0,bdi=0,bni=0;std::vector<int>bestD,bestNu;std::map<int,int>degrees;int completed=0;
for(int code=start;code<end;code++){int L;auto K=deformation(code,L);degrees[L]++;std::array<std::vector<int>,4>ds,ns;for(int cut=0;cut<2;cut++)for(int side=0;side<2;side++){int i=2*cut+side;ns[i]=smith(gflatten(K,3,3,cut,side,L,false),9);ds[i]=smith(gflatten(K,3,3,cut,side,L,true),9);for(auto&v:ds[i])v=L-v;}
for(int cut=0;cut<2;cut++)for(int a=0;a<2;a++)for(int c=0;c<2;c++){int i=2*cut+a,j=2*(1-cut)+c;double lo=0,hi=20;for(int k=0;k<80;k++){double x=(2*lo+hi)/3,y=(lo+2*hi)/3;if(objective(ds[i],ns[j],x)<objective(ds[i],ns[j],y))hi=y;else lo=x;}double t=(lo+hi)/2,B=objective(ds[i],ns[j],t);if(B<best-1e-10){best=B;bestS=std::exp(t);bestCode=code;bestDegree=L;bestD=ds[i];bestNu=ns[j];bdi=i;bni=j;std::cout<<"newbest code "<<code<<" L "<<L<<" B "<<std::setprecision(15)<<B<<" rho "<<std::log(B)/(4*std::log(3))<<std::endl;}}
completed++;if(completed%500==0)std::cout<<"completed "<<completed<<" seconds "<<std::chrono::duration<double>(std::chrono::steady_clock::now()-began).count()<<std::endl;}
auto emit=[&](std::ostream&o){o<<"{\"family\":\"ternary_nilpotent_swap_deformations\",\"field\":3,\"q\":3,\"auxiliary\":3,\"start\":"<<start<<",\"end\":"<<end<<",\"trials\":"<<completed<<",\"precision\":"<<J<<",\"best_code\":"<<bestCode<<",\"best_degree\":"<<bestDegree<<",\"best_B\":"<<std::setprecision(16)<<best<<",\"best_s\":"<<bestS<<",\"rho\":"<<std::log(best)/(4*std::log(3))<<",\"degree_cut_side\":"<<bdi<<",\"order_cut_side\":"<<bni<<",\"d\":[";for(size_t j=0;j<bestD.size();j++)o<<(j?",":"")<<bestD[j];o<<"],\"nu\":[";for(size_t j=0;j<bestNu.size();j++)o<<(j?",":"")<<bestNu[j];o<<"],\"degree_counts\":{";int j=0;for(auto [degree,count]:degrees)o<<(j++?",":"")<<"\""<<degree<<"\":"<<count;o<<"},\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-began).count()<<"}";};emit(std::cout);std::cout<<std::endl;if(!path.empty()){std::ofstream out(path);emit(out);out<<std::endl;}}
